    "国标麻将指国家体育总局在1998出台的《中国竞技麻将比赛规则(试行)》中确立的麻将规则": "MCR-Mahjong bezeichnet die Regeln, die die chinesische Sportbehörde 1998 in den „Chinesischen Wettkampfregeln für Mahjong (Versuchsfassung)“ festlegte",
