    "国标K神改。": "K-Shen-Variante von MCR.",
    "立直麻将一般指日本麻将，是麻将规则的一个分支。": "Riichi-Mahjong bezeichnet im Allgemeinen japanisches Mahjong, einen Zweig der Mahjong-Regeln.",
    "GGHK 立直麻将规则书": "GGHK Riichi-Mahjong-Regelbuch",
    "香港麻将协会发布的立直麻将规则书": "Riichi-Mahjong-Regelbuch des Mahjong-Verbands Hongkong",
    "青雀是由莫莫柴编写的一款麻雀规则，旨在寻求一种在传统麻将行牌规则框架内的做大、抢和、兜牌防守三者平衡的麻雀游戏，同时试图为各类和牌提供基于美感和难度评估的赋分参照。": "Qingque ist eine von Momochai verfasste Mahjong-Regelvariante. Innerhalb des traditionellen Spielablaufs sucht sie ein Gleichgewicht zwischen hohen Handwerten, schnellem Gewinnen und defensivem Zurückhalten von Ziegeln und versucht, Gewinnhände nach Ästhetik und Schwierigkeit zu bewerten.",
    "青雀一页纸": "Qingque auf einer Seite",
    "一页纸番种速记。": "Einseitige Übersicht der Spielbilder.",
    "青雀第十四版一页纸，来自 mmcr.online。": "Einseitige Übersicht zur 14. Qingque-Ausgabe, von mmcr.online.",
    "青雀牌例第三版第一次修订，适用于第十四版，来自 mmcr.online。": "Qingque-Handbeispiele, 3. Ausgabe, 1. Überarbeitung, passend zur 14. Regelausgabe, von mmcr.online.",
    "青雀第十四版第一次修订，来自 mmcr.online。": "Qingque, 14. Ausgabe, 1. Überarbeitung, von mmcr.online.",
    "青雀牌例": "Qingque-Handbeispiele",
    "记录规则中所有番种对应的详解及牌例。": "Ausführliche Erläuterungen und Handbeispiele zu allen Spielbildern der Regeln.",
    "青雀规则文档": "Qingque-Regeldokument",
    "包含青雀规则的行牌逻辑和概念解释。": "Enthält den Spielablauf und Begriffserklärungen der Qingque-Regeln.",
    "MIL比赛规则。": "MIL-Turnierregeln.",
    "四川麻将（SBR）竞赛规则": "Sichuan-Mahjong (SBR): Turnierregeln",
    "四川麻将（SBR）竞赛规则（试行 2025 版）。": "Sichuan-Mahjong (SBR): Turnierregeln (Versuchsfassung 2025).",
    "长沙麻将是湖南地区流行的麻将玩法。": "Changsha-Mahjong ist eine in Hunan beliebte Mahjong-Variante.",
    "长沙麻将（双鸟）规则书": "Changsha-Mahjong (Zwei Vögel): Regelbuch",
    "本平台长沙麻将的规则说明（0709 更新）。": "Regelerklärung zum Changsha-Mahjong dieser Plattform (Aktualisierung 0709).",
    "采用 144 张牌与 16 张手牌，并以台数结算的台湾麻将规则。": "Taiwanische Mahjong-Regeln mit 144 Ziegeln, 16 Ziegeln auf der Hand und Wertung in Tai.",
    "台湾麻将台数表": "Taiwanisches Mahjong: Tai-Tabelle",
    "本平台台湾麻将采用的台数参考表。": "Tai-Referenztabelle für das taiwanische Mahjong dieser Plattform.",
    "十样锦麻将": "Shiyangjin-Mahjong",
    "尚未实装该规则，此处仅提供规则书查阅。": "Diese Regeln sind noch nicht umgesetzt; hier kann nur das Regelbuch gelesen werden.",
    "十样锦麻将规则书": "Shiyangjin-Mahjong-Regelbuch",
    "十样锦麻将规则说明。": "Regelerklärung zu Shiyangjin-Mahjong.",
    "本规则为根据《绘图麻雀牌谱》《想定宁波规则》等书籍文献资料汇总而成的，试图还原1920年代左右或以前的早期麻将样貌的麻将规则。相比现代规则，古典麻雀有番种体系简单、重刻杠幺九、未和牌家计分等特点，具有独特风味。": "Diese Regeln wurden aus Büchern und historischen Quellen wie „Illustriertes Mahjong-Handbuch“ und „Rekonstruierte Ningbo-Regeln“ zusammengestellt. Sie versuchen, das frühe Mahjong um die 1920er Jahre oder davor nachzubilden. Gegenüber modernen Regeln zeichnet sich klassisches Mahjong durch ein einfaches Spielbildsystem, die Betonung von Pongs und Kongs aus Hauptziegeln sowie die Wertung nicht gewinnender Spieler aus und hat dadurch einen eigenen Charakter.",
    "平台现行的古典麻将版本。": "Die derzeit auf der Plattform verwendete klassische Mahjong-Version.",
    "■ 比赛列表": "■ Turnierliste",
    "比赛 - salasasa.cn": "Turniere - salasasa.cn",
    "13 张直接显示听牌与进张，14 张显示切牌分析（副露按等价张数计算）。输入为空时将随机生成示例。": "Bei 13 Ziegeln werden Gewinn- und Verbesserungsziegel direkt angezeigt, bei 14 Ziegeln die Abwurfanalyse (ausgelegte Figuren zählen mit ihrer entsprechenden Ziegelzahl). Bei leerer Eingabe wird ein zufälliges Beispiel erzeugt.",
    "牌面简写说明（点击展开）": "Ziegelkurzschrift erklärt (zum Aufklappen klicken)",
