    "对局开始前服务器公布承诺值 = SHA256(主种子 + 盐值)，对局结束后公布主种子与盐值。 在此本地复现随机座位与每局配牌，验证服务器未中途更换种子。计算均在浏览器内完成。": "Vor Partiebeginn veröffentlicht der Server den Commitment-Wert = SHA256(Hauptseed + Salt), nach Partieende Hauptseed und Salt. Hier kannst du die zufällige Platzvergabe und die Ziegelverteilung jeder Hand lokal nachbilden und prüfen, ob der Server den Seed zwischendurch ausgetauscht hat. Alle Berechnungen erfolgen im Browser.",
