    "本场实际打的局数；立直 / 古典的连庄也算一局（局种子序号递增）": "Tatsächlich gespielte Hände dieser Partie; Geberwiederholungen bei Riichi / klassischem Mahjong zählen ebenfalls als eine Hand (der Handseed-Index steigt)",
    "牌谱 player_entry_order 的顺序，留空则用 玩家1-4": "Reihenfolge aus player_entry_order der Aufzeichnung; bei leerer Eingabe werden Spieler 1–4 verwendet",
