    "浏览器本地转换，支持国标：雀渣 ↔ salasasa ↔ Botzone；日麻：salasasa ↔ MJAI。 反向重建（尤其 Botzone→salasasa、salasasa→雀渣）在隐藏信息处为近似，请核对后再用于训练。": "Lokale Umwandlung im Browser, unterstützt MCR: Quezha ↔ salasasa ↔ Botzone; Riichi: salasasa ↔ MJAI. Bei der Rückrekonstruktion (besonders Botzone→salasasa, salasasa→Quezha) werden verborgene Informationen angenähert. Vor der Nutzung zum Training bitte prüfen.",
