    "摸 1 万 → [\"d\", 11]；手切 3 饼 → [\"c\", 23, \"F\"]": "Zahlen-1 ziehen → [\"d\", 11]; Kreise-3 aus der Hand abwerfen → [\"c\", 23, \"F\"]",
    "番种 y → hu_fan\t完整\t用网页 FAN[] 表把番种编号还原成中文名。": "Spielbild y → hu_fan\tVollständig\tDie FAN[]-Tabelle der Webseite wandelt Spielbildnummern in chinesische Namen zurück.",
    "索引 51 → \"混一色\"；花牌×2 → \"花牌*2\"": "Index 51 → \"Unreine Farbhand\"; Blumen×2 → \"Blumenziegel*2\"",
