    "多规则同台：国标、立直、青雀、四川麻将、长沙麻将等，规则书与牌例可在站内查阅。": "Mehrere Regeln auf einer Plattform: MCR, Riichi, Qingque, Sichuan-Mahjong, Changsha-Mahjong und weitere. Regelbücher und Handbeispiele sind auf der Website verfügbar.",
    "开源可自建：项目遵循 MIT，可自行部署服务器；公共平台若因攻击等原因无法维持，规则制定者仍可自建服务。": "Offener Quellcode, selbst betreibbar: Das Projekt steht unter MIT-Lizenz und kann auf einem eigenen Server betrieben werden. Kann die öffentliche Plattform etwa wegen Angriffen nicht weitergeführt werden, können Regelautoren weiterhin eigene Dienste betreiben.",
