    "赛事用于限时比赛；基地用于长期活动室。两者并列，审批通过后申请人成为主管理员。": "Turniere sind für zeitlich begrenzte Wettbewerbe, Clubräume für langfristige Aktivitäten vorgesehen. Beide stehen gleichberechtigt nebeneinander; nach Freigabe wird der Antragsteller Hauptadministrator.",
