    "Salasasa 平台赛事规约": "Salasasa-Turnierbestimmungen",
    "赛事的组织、奖金等各项成本开支不得低于报名费的 80%，如赛事奖励中提供更上级比赛名额或特殊奖励的，可以进行独立核算。": "Die Ausgaben für Organisation, Preisgelder und weitere Turnierkosten müssen mindestens 80% der Startgebühren betragen. Startplätze für übergeordnete Wettbewerbe oder besondere Preise können gesondert abgerechnet werden.",
    "收取报名费的赛事必须明确规定赛事规则与奖励方式；该内容同样受赛事介绍中平台可能对赛制争端进行介入的声明约束。": "Turniere mit Startgebühr müssen Regeln und Preisvergabe eindeutig festlegen. Auch hierfür gilt die Erklärung in der Turnierbeschreibung, dass die Plattform bei Streit über das Format eingreifen kann.",
    "涉及烟、酒、槟榔等成瘾品赞助的赛事，须提前联系平台管理员后再申报。": "Bei Sponsoring durch Suchtmittel wie Tabak, Alkohol oder Betelnüsse muss vor der Antragstellung die Plattformverwaltung kontaktiert werden.",
    "赛事名称必须提交中文、英文或其他语言的完整赛事全称，不得使用简写、表述不清或者有公共性质的赛事名称；错误案例：国标麻将比赛、FST杯；正确案例：第一届神秘嘉宾杯国标麻将比赛、咕咕嘎嘎国标麻将群内赛。": "Der vollständige Turniername muss auf Chinesisch, Englisch oder in einer anderen Sprache eingereicht werden. Abkürzungen, unklare oder allgemein gehaltene Namen sind unzulässig. Falsch: „MCR-Mahjong-Turnier“, „FST-Cup“; richtig: „Erster Geheimnisvoller-Gast-Cup im MCR-Mahjong“, „Internes Turnier der Gugu-Gaga-MCR-Mahjong-Gruppe“.",
    "拟定开始时间 / 拟定结束时间": "Geplanter Beginn / geplantes Ende",
    "拟定开始时间": "Geplanter Beginn",
    "至": "bis",
    "拟定结束时间（可选）": "Geplantes Ende (optional)",
    "拟定开始时间和结束时间只是申请的开启赛事和关闭赛事的大致时间范围，赛事的开启与关闭将由比赛管理员自行决定；\n如果是长期的月赛或者季度赛，可以不设截止时间或连续申报比赛，在确定拟定日期以后也可以随时进行更改。": "Geplanter Beginn und geplantes Ende geben nur den ungefähren beantragten Öffnungs- und Schließungszeitraum an. Die Turnierverwaltung entscheidet selbst über Öffnung und Schließung;\nbei langfristigen Monats- oder Quartalsturnieren kann das Enddatum entfallen oder fortlaufend ein neuer Antrag gestellt werden. Festgelegte Termine können jederzeit geändert werden.",
    "赛事介绍中必须包含明确的报名联系方式，对于实际赛程这里可以不予规定、即使予以规定，后期也可以进行更改。但是，如果赛事在实际赛程中规定了某些赛事规则或者奖励方式但未达成，或者在临时更改赛制以后出现了争议或争端，平台也会一定程度上对赛事进行一些介入监管；包括且不限于，批评、取消办赛资格、封禁个别账户等惩罚，请务必注意这一点。": "Die Turnierbeschreibung muss eindeutige Kontaktangaben zur Anmeldung enthalten. Der konkrete Ablauf muss hier nicht festgelegt werden und kann auch nach einer Festlegung noch geändert werden. Werden jedoch zugesagte Regeln oder Preise nicht eingehalten oder entstehen nach einer kurzfristigen Formatänderung Streitigkeiten, kann die Plattform in gewissem Umfang eingreifen, unter anderem mit Rügen, Entzug der Veranstaltungsberechtigung oder Sperrung einzelner Konten. Bitte beachte dies unbedingt.",
    "给予管理员的审核意见，或者不希望在赛事介绍中展示、但是需要预先告知的特殊声明。": "Hinweise für die prüfende Verwaltung oder besondere Erklärungen, die vorab bekannt sein müssen, aber nicht in der Turnierbeschreibung erscheinen sollen.",
    "修改并重新提交": "Bearbeiten und erneut einreichen",
    "保存申请修改": "Antragsänderungen speichern",
    "取消修改": "Bearbeitung abbrechen",
    "查看办赛申请与已注册赛事；点击「管理」在下方展开管理面板。": "Turnieranträge und registrierte Turniere ansehen; mit „Verwalten“ den Verwaltungsbereich darunter öffnen.",
    "查看基地申请与已注册基地；点击「管理」在下方展开管理面板。": "Clubraumanträge und registrierte Clubräume ansehen; mit „Verwalten“ den Verwaltungsbereich darunter öffnen.",
    "已注册基地": "Registrierte Clubräume",
    "暂无管理中的基地": "Keine verwalteten Clubräume",
    "Salasasa 平台基地规约": "Salasasa-Clubraumbestimmungen",
    "创建基地后，玩家可以在基地中进行对局，同时管理员对对局状态、玩家牌谱与数据统计均有管理权能，如果有长期月赛或者其他非杯赛的不定期活动，使用基地来创建也是可以的。": "Nach Erstellung eines Clubraums können Spieler dort Partien spielen. Administratoren verwalten Spielzustände, Spieleraufzeichnungen und Statistiken. Clubräume können auch für laufende Monatsturniere oder unregelmäßige Aktivitäten außerhalb von Pokalturnieren verwendet werden.",
    "如果社团活动涉及烟、酒、槟榔等成瘾品赞助的相关内容，请在申请基地的介绍或者发布相关公告之前联系平台管理员。": "Enthalten Clubaktivitäten Sponsoring durch Suchtmittel wie Tabak, Alkohol oder Betelnüsse, kontaktiere die Plattformverwaltung vor der Nennung im Clubraumantrag oder der Veröffentlichung entsprechender Bekanntmachungen.",
    "基地名称必须提交中文、英文或其他语言的完整赛事全称，不得使用简写、表述不清或者有公共性质的基地名称；错误案例：「国标麻将基地」、「salasasa麻将群」、「麻将活动室」等。": "Der vollständige Name muss auf Chinesisch, Englisch oder in einer anderen Sprache eingereicht werden. Abkürzungen, unklare oder allgemein gehaltene Clubraumnamen sind unzulässig, etwa „MCR-Mahjong-Clubraum“, „salasasa-Mahjong-Gruppe“ oder „Mahjong-Aktivitätsraum“.",
    "对基地的持续时间不设限制，时间设置由基地管理员自行决定。": "Die Laufzeit von Clubräumen ist nicht begrenzt. Zeiteinstellungen bestimmt die Clubraumverwaltung selbst.",
    "基地介绍中必须包含基地/社团的简单介绍，不得留空，如果不希望对外发展社团成员，可以不留下联系方式。": "Die Clubraumbeschreibung muss eine kurze Vorstellung des Clubraums / Clubs enthalten und darf nicht leer bleiben. Werden keine neuen Mitglieder gesucht, können Kontaktangaben entfallen.",
    "给予管理员的审核意见，或者不希望在公开介绍中展示、但是需要预先告知的特殊声明。": "Hinweise für die prüfende Verwaltung oder besondere Erklärungen, die vorab bekannt sein müssen, aber nicht in der öffentlichen Beschreibung erscheinen sollen.",
    "追加备注": "Anmerkung hinzufügen",
    "可追加一条新备注，将写入双方往来记录": "Eine neue Anmerkung kann dem beidseitigen Nachrichtenverlauf hinzugefügt werden",
    "给予管理员的说明，或不希望在公开介绍中展示、但需预先告知的特殊声明。修改申请、保存修改、重新提交时填写的内容会按时间追加到双方往来备注栏。": "Erläuterungen für die Verwaltung oder besondere Erklärungen, die vorab bekannt sein müssen, aber nicht öffentlich erscheinen sollen. Bei Bearbeitung, Speicherung und erneuter Einreichung eingetragene Inhalte werden chronologisch an den beidseitigen Anmerkungsverlauf angehängt.",
    "赛事负责人": "Turnierverantwortlicher",
