    "请填写真实姓名与24小时内能够联系上的联系方式，手机号仅作为实名验证使用，如果不希望平台使用手机号进行联系，可以在备注内填写偏好的联系方式，平台绝不会通过偏好联系方式以外的方式联系您；如果不希望暴露真实姓名，可以填写惯用id，只需要手机号是实名的即可。": "Bitte echten Namen und Kontaktdaten angeben, unter denen du innerhalb von 24 Stunden erreichbar bist. Die Mobilnummer dient nur der Identitätsprüfung. Möchtest du nicht darüber kontaktiert werden, nenne den bevorzugten Kontaktweg in den Anmerkungen; die Plattform wird ausschließlich diesen verwenden. Möchtest du deinen echten Namen nicht offenlegen, kannst du deine übliche ID angeben; nur die Mobilnummer muss auf deinen echten Namen registriert sein.",
