    "第三名扣除“段位均失 PT × 0.3 × 局制系数”，第四名扣除“段位均失 PT × 0.7 × 局制系数”。东风 0.49、半庄 0.7、全庄 1。": "Platz 3 verliert „durchschnittliche Rangverlust-PT × 0.3 × Spiellängenfaktor“, Platz 4 „durchschnittliche Rangverlust-PT × 0.7 × Spiellängenfaktor“. Ostrunde 0.49, Hanchan 0.7, vier Runden 1.",
