    "国标十六张：扩展规则与牌例": "MCR mit sechzehn Ziegeln: Erweiterungsregeln und Handbeispiele",
    "以新编 MCR 为底本的本站十六张扩展，含逐番适用表与五面子计分补则。": "Die Sechzehn-Ziegel-Erweiterung dieser Website auf Basis der MCR-Neufassung, mit Anwendbarkeitstabelle je Spielbild und ergänzender Wertung für fünf Figuren.",
    "四人立直麻将，支持多种规则预设及役种、计分和流局设置": "Riichi-Mahjong für vier Spieler, mit verschiedenen Regelvorlagen sowie Einstellungen für Yaku, Wertung und Unentschieden",
    "香港麻将协会发布的立直麻将规则书。": "Riichi-Mahjong-Regelbuch des Mahjong-Verbands Hongkong.",
    "全国雀庄公式战手册 v1.0": "Handbuch für offizielle Spiele landesweiter Mahjong-Salons v1.0",
    "雀庄公式战预设所依据的公开手册。": "Öffentliches Handbuch als Grundlage der Vorlage für offizielle Salonspiele.",
    "查看公开手册": "Öffentliches Handbuch ansehen",
    "台湾麻将：使用144张牌与16张手牌，按台计分，支持公开报听、食替限制与八仙过海等规则。具体流程与台表可在馆规设置中选择。": "Taiwanisches Mahjong: 144 Ziegel, 16 auf der Hand, Wertung in Tai. Unterstützt öffentliche Warteansagen, Tauschrufbeschränkungen, Acht Unsterbliche überqueren das Meer und weitere Regeln. Ablauf und Tai-Tabelle sind in den Hausregeln wählbar.",
    "四川麻将（血战到底）": "Sichuan-Mahjong (Kampf bis zum Ende)",
    "长沙麻将经典双鸟规则：108张数牌，可吃上家牌，258将小胡，大胡可叠加，和牌后翻两只鸟并按座位中鸟加倍。": "Klassische Changsha-Regeln mit zwei Vögeln: 108 Farbziegel, Chi vom linken Spieler, kleine Gewinne mit 2er-, 5er- oder 8er-Paar, kombinierbare große Gewinne. Nach dem Gewinn werden zwei Vögel aufgedeckt; Treffer nach Sitzplatz verdoppeln die Wertung.",
    "本平台长沙麻将规则说明。": "Regelerklärung zum Changsha-Mahjong dieser Plattform.",
    "也叫 MCR、中国麻将竞赛规则": "Auch MCR oder Chinesische Mahjong-Wettkampfregeln genannt",
