    "地方规则与未定年线索": "Regionale Regeln und undatierte Hinweise",
    "多版／平台伞称（1998原本另列）": "Sammelbegriff für mehrere Fassungen / Plattformen (Original von 1998 gesondert)",
    "国标麻将规则资料，包含 Natsuki 编著的《新编 MCR》及各改编版本规则书。": "MCR-Regelmaterialien einschließlich Natsukis „MCR-Neufassung“ und Regelbüchern verschiedener Abwandlungen.",
    "国标是多版规则及平台实现的伞称。1998原本题署7月、9月初版；WMO 2006和赛事补充须另看具名版本。平台使用的新编MCR不应与1998全文等同，原目录11月出台说已按原书更正。": "MCR ist ein Sammelbegriff für mehrere Regelfassungen und Plattformumsetzungen. Das Original von 1998 ist auf Juli datiert, die Erstauflage erschien im September. WMO 2006 und Turnierergänzungen müssen als eigene Fassungen betrachtet werden. Die MCR-Neufassung der Plattform ist nicht mit dem vollständigen Text von 1998 gleichzusetzen. Die frühere Katalogangabe einer Veröffentlichung im November wurde anhand des Originalbuchs berichtigt.",
    "国标麻将（新编 MCR）": "MCR-Mahjong (MCR-Neufassung)",
