    "账户没有绑定邮箱？联系测试群群主手动找回密码，": "Keine E-Mail mit dem Konto verknüpft? Kontaktiere den Leiter der Testgruppe zur manuellen Passwortwiederherstellung,",
    "选择转换方向": "Umwandlungsrichtung auswählen",
