    "各加计8番：天和为庄家起手自摸；地和为闲家和庄家首张弃牌；人和为闲家首次摸牌自摸。全桌吃碰杠（含暗杠）打断，补花不打断。": "Je zusätzlich 8 Fan: Himmelsgewinn ist der Selbstziehgewinn des Gebers mit der Starthand; Erdgewinn der Gewinn eines Nichtgebers mit dem ersten Geberabwurf; Menschengewinn der Selbstziehgewinn eines Nichtgebers beim ersten Ziehen. Chi, Pong und Kong (auch verdeckt) eines beliebigen Spielers unterbrechen die Bedingung, Blumenersatz nicht.",
