    "宝牌输入实际张数。四人日麻：食断、累计役满、复合役满开启；双倍役满、切上满贯关闭。不含本场与供托。": "Tatsächliche Dora-Anzahl eingeben. Vierer-Riichi: offenes Tanyao, gezähltes Yakuman und kombinierte Yakuman an; doppelte Yakuman und Aufrunden auf Mangan aus. Ohne Honba und Riichi-Einsätze.",
