    "副露用括号编码并区分大小写：": "Ausgelegte Figuren werden in Klammern mit Groß-/Kleinschreibung codiert:",
    "为二三四万明顺，": "steht für eine offene Folge Zahlen 2-3-4,",
    "为三饼暗刻；编码中的数字为项目牌号。": "für einen verdeckten Pong Kreise-3; die Zahlen im Code sind die Ziegelnummern des Projekts.",
    "表示明顺 / 暗顺（数字取顺子中间牌）；": "steht für offene / verdeckte Folge (mit der Zahl des mittleren Ziegels);",
