    "项目牌号：11–19 万、21–29 饼、31–39 条、41–44 东南西北、45 中、46 白、47 发；与": "Projekt-Ziegelnummern: 11–19 Zahlen, 21–29 Kreise, 31–39 Bambus, 41–44 Ost Süd West Nord, 45 Rot, 46 Weiß, 47 Grün; die Reihenfolge unterscheidet sich von",
    "简写顺序不同。": "in der Kurzschrift.",
