    "后为单张和牌张。副露与简写双向同步，删除括号编码也会移除对应副露。": "danach folgt ein einzelner Schlussziegel. Ausgelegte Figuren und Kurzschrift werden gegenseitig synchronisiert; das Löschen eines Klammercodes entfernt auch die entsprechende Figur.",
    "■ 麻雀计算器与猜番": "■ Mahjong-Rechner und Fan-Quiz",
    "分析向听、进张与切牌，并计算和牌番种、得分及全部拆解。": "Shanten, Verbesserungsziegel und Abwürfe analysieren sowie Gewinnspielbilder, Punkte und sämtliche Zerlegungen berechnen.",
