    "<color=#05B852>状态：进行中</color>\n开始时间：2026-07-15\n结束时间：未定\n<color=#E6B814>资格：未报名</color>\n<color=#E6B814>自动通过报名：否</color>\n<color=#E6B814>允许未报名玩家创建房间：否</color>\n<color=#E6B814>允许未报名玩家进入队列：否</color>": "<color=#05B852>Status: läuft</color>\nBeginn: 2026-07-15\nEnde: offen\n<color=#E6B814>Teilnahme: nicht angemeldet</color>\n<color=#E6B814>Anmeldung automatisch genehmigen: nein</color>\n<color=#E6B814>Nicht angemeldete Spieler dürfen Räume erstellen: nein</color>\n<color=#E6B814>Nicht angemeldete Spieler dürfen sich einreihen: nein</color>",
