    "我想添加自己的麻将规则\n(点击这里)": "Ich möchte eigene Mahjong-Regeln hinzufügen\n(hier klicken)",
    "北京麻将（吃碰提）是北京地区的民间麻将规则，其特点为有字牌、无花牌、有万能牌、非门前清状态不可点和，番种体系较为简单。本文参考网络资料与线下实践梳理北京麻将的基本玩法，体现北京麻将核心特征，便于各地麻将爱好者了解北京麻将主要框架。": "Peking-Mahjong (Chi-Pong-Ti) ist eine regionale Mahjong-Spielweise aus Peking. Es verwendet Bildziegel, keine Blumen, aber Joker; offene Hände können nicht durch Abwurf gewinnen, und das Spielbildsystem ist relativ einfach. Dieser Text fasst anhand von Internetquellen und praktischen Erfahrungen die Grundregeln und Kerneigenschaften zusammen, damit Mahjong-Spieler anderer Regionen den wesentlichen Aufbau kennenlernen können.",
