    "  项目简介": "  Projektübersicht",
    "open_mahjong_unity是一款基于unity/python-fastapi的麻将平台项目，该项目遵循MIT许可协议、免费、开源、支持PC/安卓/ios三端互通；目标是支持所有麻将规则、并且提供给玩家自定义规则的选项。欢迎加入q群906497522参与讨论、协助和测试。": "open_mahjong_unity ist ein kostenloses, quelloffenes Mahjong-Plattformprojekt auf Basis von unity/python-fastapi unter MIT-Lizenz und unterstützt gemeinsames Spielen auf PC/Android/iOS. Ziel ist die Unterstützung aller Mahjong-Regeln mit der Möglichkeit eigener Regeln. Tritt der QQ-Gruppe 906497522 bei, um mitzudiskutieren, mitzuhelfen und zu testen.",
    "  随机种子": "  Zufallsseed",
    "在玩家 A 出牌时，若玩家 B、C 可对该出牌进行操作，则 B、C 会提前看到这张出牌；玩家 D 则会延迟一个「鸣牌保护时间」才看到出牌。若在鸣牌保护时间内 B、C 对出牌进行了操作，玩家 D 会立刻看见出牌，并在「第一追赶时间」之后再看见 B、C 其一执行的鸣牌申请或鸣牌。\n\n由于玩家 D 必定延迟一个第一追赶时间才看见 B、C 其一的鸣牌，若 B、C 在吃碰后快速出牌，这张出牌在 D 的视角中会显得「即时」。因此平台在触发鸣牌保护后进行出牌时，会保证至少再经过「第二追赶时间」才播放动画，避免在 D 的视角中出牌紧贴在吃碰之后生效。\n\n当前默认配置：\n鸣牌保护时间：1.3s\n第一追赶时间：0.7s\n第二追赶时间：0.5s": "Wirft A einen Ziegel ab, auf den B und C reagieren können, sehen B und C ihn vorab; D sieht ihn erst nach einer „Rufschutzzeit“. Reagiert B oder C innerhalb dieser Zeit, sieht D den Abwurf sofort und nach der „ersten Aufholzeit“ die Rufanfrage oder den Ruf von B oder C.\n\nDa D diesen Ruf stets erst nach der ersten Aufholzeit sieht, könnte ein schneller Abwurf nach Chi oder Pong aus seiner Sicht „sofort“ erscheinen. Nach ausgelöstem Rufschutz wartet die Plattform deshalb vor der Abwurfanimation mindestens noch eine „zweite Aufholzeit“, damit der Abwurf für D nicht unmittelbar auf Chi oder Pong folgt.\n\nAktuelle Standards:\nRufschutzzeit: 1.3s\nErste Aufholzeit: 0.7s\nZweite Aufholzeit: 0.5s",
    "战术鸣牌的设计来源于雀渣：在其他家申请鸣牌以后，可用更高优先级的操作打断他家更低优先级的操作，以模拟线下刻意「碰断吃」等战术。\n\n示例一：玩家 A 出牌 T，玩家 B 可吃、玩家 C 可碰。此时 C 选择跳过，但 B 点击了吃牌；由于仍存在可执行的更高优先级操作，系统会再次询问 C 是否要碰，以模拟国标线下允许刻意用碰打断别人吃的情形。\n\n示例二：玩家 A 出牌 T，玩家 B 可吃或和牌，玩家 C 可碰。B 选择吃，C 用碰打断了 B 的吃；此时 B 不再能用和去打断 C 的碰。这符合国标不允许玩家在鸣牌发声后更改自己要执行动作的规则。": "Taktische Rufe stammen aus Quezha: Nach der Rufanfrage eines Mitspielers kann eine höher priorisierte Aktion seine niedriger priorisierte Aktion unterbrechen, um Taktiken am echten Tisch wie absichtliches „Pong unterbricht Chi“ nachzubilden.\n\nBeispiel 1: A wirft T ab, B kann Chi und C Pong rufen. C passt zunächst, doch B wählt Chi. Da eine höher priorisierte Aktion noch möglich ist, fragt das System C erneut nach Pong. Das bildet die im MCR am echten Tisch erlaubte absichtliche Unterbrechung eines Chi durch Pong nach.\n\nBeispiel 2: A wirft T ab, B kann Chi oder Gewinn und C Pong rufen. B wählt Chi, C unterbricht es mit Pong. B kann Cs Pong nun nicht mehr durch Gewinn unterbrechen. Das entspricht der MCR-Regel, dass die gewählte Aktion nach einem Ruf nicht geändert werden darf.",
    "  添加规则": "  Regeln hinzufügen",
