    "手牌牌面背景：用于在手牌牌面使用透明通道的情况下替换背景，默认尺寸 272*389。\n手牌牌背：用于在里宝牌区或者2D展示中显示牌背\n3D牌面背景：用于在3D卡牌的正面叠底在3D花纹下显示\n上传成对 zip格式：hand-back.png + hand-bg.png。": "Handziegelhintergrund: ersetzt den Hintergrund bei transparenten Handziegelflächen, Standardgröße 272*389.\nHandziegelrückseite: zeigt Rückseiten im Ura-Dora-Bereich oder in 2D\n3D-Ziegelhintergrund: liegt auf der Vorderseite von 3D-Ziegeln unter dem 3D-Muster\nZIP-Format des Bildpaars: hand-back.png + hand-bg.png.",
