    "国标麻将：初级场\n入场门槛：无\n场得pt：30\n场失pt：依照段位\n分配比例：+8+2-3-7\n对局设置：番数提示 无错和\n时间限制：20+5": "MCR-Mahjong: Anfängerraum\nZugangsvoraussetzung: keine\nPT-Gewinn je Partie: 30\nPT-Verlust je Partie: nach Rang\nVerteilung: +8+2-3-7\nSpieleinstellungen: Fan-Hinweise, keine falschen Gewinnrufe\nZeitlimit: 20+5",
