    "段位 PT = q ×（k × M - C）；q 为局制系数，k 为场次倍率，C 见段位扣分表": "Rang-PT = q × (k × M - C); q ist der Spiellängenfaktor, k der Spielklassenmultiplikator, C steht in der Rangabzugstabelle",
