    "PT 计算": "PT-Berechnung",
    "普通入场段位": "Regulärer Zugangsrang",
    "C 为负数时是保护奖励；PT 保留两位小数。十段固定 100/100 PT，每场变动为 0。": "Ein negatives C ist ein Schutzbonus; PT werden mit zwei Dezimalstellen geführt. Der 10. Dan bleibt bei 100/100 PT, Änderung je Partie 0.",
    "立直 · 段位升降与扣分表": "Riichi · Rangaufstieg, Rangabstieg und Abzüge",
    "各名次扣相同的 C；东风整体乘 0.7，负数为保护奖励。特许可突破最低段位；— 为禁入场次。": "Für alle Plätze wird dasselbe C abgezogen; in der Ostrunde wird alles mit 0.7 multipliziert. Negative Werte sind Schutzboni. Sonderberechtigungen können den Mindestrang unterschreiten; — bedeutet kein Zugang.",
