    "暂无物品": "Keine Gegenstände",
    "装扮": "Dekoration",
    "点击改名": "Zum Umbenennen klicken",
    "段位与匹配说明": "Ränge und Spielvermittlung",
    "为适配不同人数的游玩规则的匹配机制，平台目前提供以下两种段位设计\n1.对于每日对于超过100局的麻将规则，使用以级段制为主的段位系统\n2.对于每日对局低于100局的麻将规则，使用以elo为主的匹配系统进行对局，待人数提升后，按照elo排名设计级段制段位，并通过elo对玩家的段位进行赋分\n3.对于娱乐、开发中或不需添加段位机制的规则，不开设段位匹配场": "Für Regeln mit unterschiedlicher Spielerzahl bietet die Plattform derzeit folgende zwei Rangsysteme:\n1. Bei Mahjong-Regeln mit über 100 Partien täglich wird vorwiegend ein Kyu-/Dan-Rangsystem verwendet.\n2. Bei Regeln mit unter 100 Partien täglich vermittelt vorwiegend ein Elo-System die Spiele. Bei steigender Spielerzahl werden anhand der Elo-Rangliste Kyu-/Dan-Ränge entworfen und die Spieler nach Elo eingestuft.\n3. Für Unterhaltungsregeln, Regeln in Entwicklung oder Regeln ohne Bedarf an einem Rangsystem gibt es keine Ranglistenvermittlung.",
    "Elo 匹配\n\n各规则独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副）。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32；川麻 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n青雀使用独立的局均素点算法，详见青雀页面。国标、立直仅结算段位/PT；自定义对局不计分。": "Elo-Vermittlung\n\nJede Regel wird unabhängig gewertet. Hongque bietet Hanchan mit 8 oder vier Runden mit 16 Händen; Sichuan Kampf bis zum Ende und Blutfluss mit Dreiertausch verwenden Hanchan (8 Hände). Vermittelt wird nach Eintrittsreihenfolge; mit vier Spielern startet die Partie sofort.\nStart-R = 1500, Nenner 2400. Hongque Hanchan K=16, vier Runden K=32; Sichuan K=32. Die Endplatzierung wird mit allen drei Gegnern verglichen; gleiche Plätze gelten als Unentschieden. Bei einem Tischdurchschnitt R unter 1500 kommt ein Schutzbonus hinzu, ohne persönliche Untergrenze.\n\nQingque verwendet einen eigenen Algorithmus auf Basis der Rohpunkte je Hand, siehe Qingque-Seite. MCR und Riichi werten nur Rang/PT; eigene Partien bleiben ungewertet.",
    "放弃比赛": "Partie aufgeben",
    "检测到您有一场正在进行的游戏，是否返回游戏?": "Eine laufende Partie wurde gefunden. Zum Spiel zurückkehren?",
    "刷新房间列表成功": "Raumliste erfolgreich aktualisiert",
    "Elo 匹配\n\n青雀、虹雀、川麻血战、血流换三张独立计分。虹雀可选半庄8局或全庄16局，川麻血战和血流换三张为半庄战（8副），青雀为全庄战。按加入顺序匹配，满四人立即进入对局。\n初始 R = 1500，分母 2400。虹雀半庄 K=16，全庄 K=32，两种局制共用虹雀积分；其他 Elo 规则 K=32。按最终名次比较三个对手，并列算平局。桌均 R 低于 1500 时追加保护，不设个人保底。\n\n问号内显示算法。国标、立直仅结算段位/PT；自定义对局不计分。": "Elo-Vermittlung\n\nQingque, Hongque, Sichuan Kampf bis zum Ende und Blutfluss mit Dreiertausch werden unabhängig gewertet. Hongque bietet Hanchan mit 8 oder vier Runden mit 16 Händen, Sichuan Kampf bis zum Ende und Blutfluss mit Dreiertausch Hanchan (8 Hände), Qingque vier Runden. Vermittelt wird nach Eintrittsreihenfolge; mit vier Spielern startet die Partie sofort.\nStart-R = 1500, Nenner 2400. Hongque Hanchan K=16, vier Runden K=32; beide Spiellängen teilen dieselben Hongque-Punkte. Andere Elo-Regeln verwenden K=32. Die Endplatzierung wird mit allen drei Gegnern verglichen; gleiche Plätze gelten als Unentschieden. Bei Tischdurchschnitt R unter 1500 kommt ein Schutzbonus hinzu, ohne persönliche Untergrenze.\n\nDas Fragezeichen zeigt den Algorithmus. MCR und Riichi werten nur Rang/PT; eigene Partien bleiben ungewertet.",
