    "把牌先分成三类：数牌、字牌、花牌。\n不用急着记番种，今天先认清牌面。": "Teile die Ziegel zunächst in drei Gruppen: Farbziegel, Bildziegel und Blumen.\nDie Spielbilder müssen noch nicht gelernt werden; heute lernen wir erst die Ziegelflächen kennen.",
