    "欢迎来到麻雀教室！我是琪露诺。先一起认识麻将牌吧——数牌 108 张，字牌 28 张，再加 8 张花牌。": "Willkommen im Mahjong-Klassenzimmer! Ich bin Cirno. Lernen wir zuerst die Mahjong-Ziegel kennen: 108 Farbziegel, 28 Bildziegel und 8 Blumen.",
