    "<b>青雀 · 局均素点 Elo</b>\n初始 R = 1500；全庄与无固定时限共用积分。\nN = 实际完成局数（包含流局），Y = 累计净素点。\n局均 A = Y / N；桌均 M = 四人 R 的平均值。\n预期局均 = (自己 R - M) / 32\n普通变化 = 32N / (N + 1584) × (A - 预期局均)\n不按名次计分，不设涨跌硬上限。\n保护系数 K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((对手 R - 自己 R) / 2400))\nE' = 1 / (1 + 10^((对手 R + T - 自己 R) / 2400))\n指数限制在 -16 至 16；合计为三个对手之和。\n保护奖励 = (K / 3) × 合计(E - E')\n新 R = 原 R + 普通变化 + 保护奖励。\n普通变化按分币分配余差保持零和，保护另取两位。\n同为1500分、16局：净赢800加16，1600加32。\n未完成局不计入；零完成局不结算。": "<b>Qingque · Elo nach Rohpunkten je Hand</b>\nStart-R = 1500; vier Runden und Spiele ohne feste Zeitgrenze teilen dieselbe Wertung.\nN = tatsächlich abgeschlossene Hände (einschließlich Unentschieden), Y = kumulierte Netto-Rohpunkte.\nHanddurchschnitt A = Y / N; Tischdurchschnitt M = Durchschnitt der vier R-Werte.\nErwarteter Handdurchschnitt = (eigenes R - M) / 32\nNormale Änderung = 32N / (N + 1584) × (A - erwarteter Handdurchschnitt)\nKeine Wertung nach Platzierung, keine feste Obergrenze für Anstieg oder Verlust.\nSchutzfaktor K = 3200N / (N + 1584)\nT = max(0, 1500 - M)\nE = 1 / (1 + 10^((Gegner-R - eigenes R) / 2400))\nE' = 1 / (1 + 10^((Gegner-R + T - eigenes R) / 2400))\nExponent auf -16 bis 16 begrenzt; summiert wird über die drei Gegner.\nSchutzbonus = (K / 3) × Summe(E - E')\nNeues R = bisheriges R + normale Änderung + Schutzbonus.\nRundungsreste der normalen Änderung werden in Hundertsteln verteilt, um die Nullsumme zu erhalten; der Schutzbonus wird separat auf zwei Stellen gerundet.\nBei je 1500 Punkten und 16 Händen: 800 Nettogewinn ergibt +16, 1600 ergibt +32.\nUnvollständige Hände zählen nicht; ohne abgeschlossene Hand keine Abrechnung.",
