    "日麻规则下的三元牌排列示例。": "Beispiel der Drachenreihenfolge bei Riichi.",
    "调整万、索、饼的排列顺序，下方手牌同步预览。": "Reihenfolge von Zahlen, Bambus und Kreisen anpassen; die Handvorschau unten folgt sofort.",
    "调整字牌与数牌的先后顺序，下方手牌同步预览。": "Reihenfolge von Bild- und Farbziegeln anpassen; die Handvorschau unten folgt sofort.",
    "调整非日麻规则下中、发、白的排列顺序。": "Reihenfolge von Rot, Grün und Weiß außerhalb von Riichi anpassen.",
    "调整日麻规则下中、发、白的排列顺序。": "Reihenfolge von Rot, Grün und Weiß bei Riichi anpassen.",
    "切换白板牌面的纯白或回形样式。": "Weißen Drachen zwischen reinweißem und eingerahmtem Design umschalten.",
    "设置对局操作按钮是否使用分类颜色。": "Festlegen, ob Spielaktionsschaltflächen Kategorienfarben verwenden.",
    "3D 牌描边使用标准样式。": "Standardkonturen für 3D-Ziegel verwenden.",
    "设置副露牌组之间是否留出间距；规则要求时固定开启。": "Abstände zwischen ausgelegten Figuren festlegen; bei Regelvorgabe dauerhaft aktiviert.",
    "切换游戏界面的显示语言。": "Anzeigesprache der Spieloberfläche wechseln.",
    "设置画面帧率上限；开启垂直同步时由同步设置决定。": "Maximale Bildrate festlegen; bei aktivierter vertikaler Synchronisierung gilt deren Einstellung.",
    "让画面刷新与显示器同步，减少画面撕裂。": "Bildausgabe mit dem Monitor synchronisieren, um Bildrisse zu verringern.",
    "当前规则固定开启副露间距。": "Die aktuellen Regeln schreiben Abstände zwischen ausgelegten Figuren vor.",
