    "特殊和牌型 · 连续七对": "Sondergewinnhand · Sieben aufsteigende Paare",
    "特殊和牌型 · 最右一张为和牌张": "Sondergewinnhand · Ganz rechts der Schlussziegel",
    "四组刻子均为暗刻；自摸和牌": "Alle vier Pongs sind verdeckt; Selbstziehgewinn",
