    " · 番种记录": " · Spielbildaufzeichnungen",
    "日汇总截止 ": "Tagesübersicht bis ",
    "平台累计\n按当前规则及场次读取公开牌谱统计，对局按 game_id 去重。全场次含匹配、自定义和赛事；四张场次卡始终展示当前规则的累计数量。\n\n匹配场行为数据\n累计手数为全桌手数；平均和牌 = 总和牌番值 ÷ 和牌次数；自摸占和牌 = 自摸次数 ÷ 和牌次数。不展示个人胜率和个人顺位。\n\n每日对局量\n时间窗口只作用于日汇总，不改变累计指标与最近牌谱。统计日以北京时间 04:00 切日，截止最近已完成聚合日。缺少记录的日期留空，不补零。\n\n场次与局制\n初级、中级、高级、自定义的累计计数来自网站首页的原始牌谱归口接口。自定义部分缺少完整行为指标，只展示已提供的对局计数。\n\n最近对局\n全场次时展示匹配场公共牌谱，可按等级场筛选、翻页并查看同桌结算。赛事单独查询；现有接口未提供自定义房间公共牌谱列表。\n\n番种记录\n累计出现次数可重复，不是互斥占比。所选场次无支持时显示不可用。": "Plattformgesamtwerte\nÖffentliche Spielprotokollstatistiken werden nach den aktuellen Regeln und der Spielklasse gelesen; Partien werden anhand der game_id dedupliziert. Alle Spielklassen umfassen Spielersuche, eigene Räume und Turniere. Die vier Spielklassenkarten zeigen stets die Gesamtzahlen der aktuellen Regeln.\n\nSpielverhalten in der Spielersuche\nDie Handzahl zählt die Hände des gesamten Tisches. Durchschnittlicher Gewinnwert = gesamte Fan der Gewinne ÷ Anzahl der Gewinne. Selbstzuganteil an Gewinnen = selbstgezogene Gewinne ÷ Anzahl der Gewinne. Persönliche Gewinnquoten und Platzierungen werden nicht angezeigt.\n\nTägliche Partiezahl\nDas Zeitfenster gilt nur für Tagesübersichten, nicht für Gesamtkennzahlen und letzte Spielprotokolle. Ein Statistiktag wechselt um 04:00 Uhr Pekinger Zeit. Die Übersicht endet am letzten vollständig zusammengefassten Tag. Tage ohne Aufzeichnungen bleiben leer und werden nicht mit null ergänzt.\n\nSpielklassen und Partielänge\nDie Gesamtzahlen für Anfänger, Mittelstufe, Fortgeschrittene und eigene Räume stammen aus der ursprünglichen Spielprotokoll-Zuordnungsschnittstelle der Startseite. Für eigene Räume fehlen teilweise vollständige Verhaltenskennzahlen; dort werden nur verfügbare Partiezahlen angezeigt.\n\nLetzte Partien\nBei allen Spielklassen werden öffentliche Protokolle der Spielersuche angezeigt. Sie lassen sich nach Spielklasse filtern, durchblättern und mit der Tischabrechnung öffnen. Turniere werden separat abgefragt. Die bestehende Schnittstelle liefert keine öffentliche Spielprotokollliste für eigene Räume.\n\nSpielbildaufzeichnungen\nVorkommen werden kumuliert und können mehrfach zählen; es sind keine sich gegenseitig ausschließenden Anteile. Bei fehlender Unterstützung der gewählten Spielklasse wird „Nicht verfügbar“ angezeigt.",
    "符": "Fu",
    "台": "Tai",
    "点": "Punkte",
    " 局": " Hände",
    "已解析 ": "Ausgewertet: ",
    " 场": " Partien",
    "本规则暂未提供逐局统计": "Für diese Regeln gibt es noch keine Statistik pro Hand",
    "统计范围\n所选规则、房间类型与日期同时作用于战绩和对局列表。\n\n和牌率 / 放铳率\n个人和牌次数 / 放铳次数 ÷ 参与的手数。\n\n自摸占和牌\n自摸次数 ÷ 和牌次数；不是每手自摸率。\n\n副露率\n个人副露手数 ÷ 参与的手数。\n\n平均顺位\n各顺位场次 × 顺位之和 ÷ 总场次。\n\n番种记录\n记录累计出现次数，可重复计数，不是互斥占比。\n\n近期走势\n最近最多 20 场，按时间从旧到新。缺少明细的指标显示“—”。": "Statistikumfang\nDie gewählten Regeln, Raumart und Daten gelten zugleich für Bilanz und Partieliste.\n\nGewinnquote / Reinspielquote\nEigene Gewinne / eigenes Reinspielen ÷ gespielte Hände.\n\nSelbstzuganteil an Gewinnen\nSelbstgezogene Gewinne ÷ Gewinne; keine Selbstzugquote pro Hand.\n\nRufquote\nEigene Hände mit offenem Ruf ÷ gespielte Hände.\n\nDurchschnittsplatz\nSumme aus Anzahl der Partien je Platz × Platznummer ÷ Gesamtpartien.\n\nSpielbildaufzeichnungen\nKumulierte Vorkommen, auch mehrfach gezählt; keine sich gegenseitig ausschließenden Anteile.\n\nJüngster Verlauf\nHöchstens die letzten 20 Partien, von alt nach neu. Kennzahlen ohne Details erscheinen als „—“.",
