    "与当前服务器匹配的新安装包尚未就绪，可能仍在上传，请稍后重试。": "Das zur aktuellen Serverversion passende Installationspaket ist noch nicht bereit und wird möglicherweise noch hochgeladen. Bitte später erneut versuchen.",
