    "牌例：": "Handbeispiel: ",
    "东、南、西、北分别组成四组刻子或杠子，另有一对将。": "Je ein Pong oder Kong aus Ost, Süd, West und Nord sowie ein Paar.",
    "中、发、白三组箭牌刻子或杠子，另有一组面子和将。": "Drei Pongs oder Kongs aus roten, grünen und weißen Drachen sowie eine weitere Figur und ein Paar.",
    "仅使用 23468 条与发牌，例如 234678 条刻顺组合。": "Nur 23468 Bambus und grüne Drachen, etwa eine Kombination aus Pongs und Chis mit 234678 Bambus.",
    "同一门 1112345678999 加该门任一张牌。": "1112345678999 einer Farbe und ein beliebiger weiterer Ziegel dieser Farbe.",
    "四组杠子，剩余一对将牌组成和牌。": "Vier Kongs und ein Paar bilden die Gewinnhand.",
    "同一门连续七个对子，例如 11223344556677 万。": "Sieben aufeinanderfolgende Paare einer Farbe, etwa 11223344556677 Zahlen.",
    "一、九万饼条与东南西北中发白各一张，再成一对。": "Je eine Eins und Neun in Zahlen, Kreisen und Bambus sowie Ost, Süd, West, Nord, roter, grüner und weißer Drache; dazu ein Paar.",
    "只由万、饼、条的一九牌组成刻子、杠子和将牌。": "Pongs, Kongs und Paar ausschließlich aus Einsen und Neunen in Zahlen, Kreisen und Bambus.",
    "东南西北中三组刻子或杠子，第四组为对子。": "Drei Pongs oder Kongs aus Ost, Süd, West und Nord; der vierte Wind bildet das Paar.",
    "中、发、白中两组刻子，一组对子，另有两组面子。": "Zwei Pongs und ein Paar aus den drei Drachen sowie zwei weitere Figuren.",
    "手牌全部由东南西北中发白组成。": "Die gesamte Hand besteht aus Ost, Süd, West, Nord, roten, grünen und weißen Drachen.",
    "四组暗刻或暗杠，另有一对将牌。": "Vier verdeckte Pongs oder Kongs sowie ein Paar.",
    "一门 112233、556677、99 的七对结构。": "Sieben Paare in der Struktur 112233, 556677, 99 einer Farbe.",
    "同一门四组完全相同的顺子，例如四组 123 万。": "Vier völlig gleiche Chis einer Farbe, etwa viermal 123 Zahlen.",
    "同一门四组连续递增的刻子，例如 111、222、333、444。": "Vier aufeinanderfolgende Pongs einer Farbe, etwa 111, 222, 333, 444.",
    "同一门四组连续递进的顺子。": "Vier aufeinanderfolgend verschobene Chis einer Farbe.",
    "三组杠子，另有一组面子和将牌。": "Drei Kongs sowie eine weitere Figur und ein Paar.",
    "万、饼、条的一九刻子与字牌刻子混合组成全副牌。": "Die gesamte Hand kombiniert Einsen- und Neunenpongs in Zahlen, Kreisen und Bambus mit Bildziegelpongs.",
    "七个不同对子，例如 11223344556677。": "Sieben verschiedene Paare, etwa 11223344556677.",
    "七张字牌齐全，另有三门各三张不相连序数牌。": "Alle sieben Bildziegel sowie je drei nicht verbundene Farbziegel in den drei Farben.",
    "全部由 2、4、6、8 序数牌组成的刻子和将牌。": "Pongs und Paar ausschließlich aus den Zahlen 2, 4, 6 und 8.",
    "整副牌只使用万、饼或条中的一门。": "Die gesamte Hand verwendet nur Zahlen, Kreise oder Bambus.",
    "同一门三组完全相同的顺子。": "Drei völlig gleiche Chis einer Farbe.",
    "同一门三组连续递增的刻子。": "Drei aufeinanderfolgende Pongs einer Farbe.",
    "所有序数牌均为 7、8、9。": "Alle Farbziegel haben die Zahlen 7, 8 oder 9.",
    "所有序数牌均为 4、5、6。": "Alle Farbziegel haben die Zahlen 4, 5 oder 6.",
    "所有序数牌均为 1、2、3。": "Alle Farbziegel haben die Zahlen 1, 2 oder 3.",
    "同一门 123、456、789 三组顺子。": "Die drei Chis 123, 456 und 789 einer Farbe.",
    "三门各有 112233、556677、99 的双龙七对结构。": "Eine Sieben-Paare-Struktur mit zwei Drachen aus 112233, 556677 und 99 in den drei Farben.",
    "同一门三组按相同步长递进的顺子。": "Drei Chis einer Farbe, die jeweils um denselben Schritt verschoben sind.",
    "每组面子和将牌都含有 5，例如 123、456、789。": "Jede Figur und das Paar enthalten eine 5, etwa 123, 456, 789.",
    "三门各有同一序数的刻子，例如 555 万、555 饼、555 条。": "Je ein Pong derselben Zahl in allen drei Farben, etwa 555 Zahlen, 555 Kreise und 555 Bambus.",
    "三组暗刻或暗杠，另有一组面子和将牌。": "Drei verdeckte Pongs oder Kongs sowie eine weitere Figur und ein Paar.",
    "三门序数牌互不相连，且不含重复，配字牌组成特殊牌型。": "Nicht verbundene Farbziegel der drei Farben ohne Wiederholungen, mit Bildziegeln zu einer Sonderhand kombiniert.",
    "三门各取 147、258、369 之一组成组合龙。": "Je eine der Reihen 147, 258 und 369 in den drei Farben bildet die Verknüpfte Reihe.",
    "全部序数牌均为 6、7、8、9。": "Alle Farbziegel haben die Zahlen 6, 7, 8 oder 9.",
    "全部序数牌均为 1、2、3、4。": "Alle Farbziegel haben die Zahlen 1, 2, 3 oder 4.",
    "东南西北中任取三组风牌刻子或杠子。": "Drei Pongs oder Kongs aus beliebigen Winden: Ost, Süd, West und Nord.",
    "三门各有一组相连的顺子，合起来形成 123、456、789。": "Je ein Chi in drei Farben ergibt zusammen 123, 456 und 789.",
    "只使用牌面旋转后仍有对应关系的牌，如 123689 饼及白板。": "Nur Ziegel, deren Bild nach einer Drehung weiterhin passt, etwa 123689 Kreise und weiße Drachen.",
    "三门各有同一数字的顺子，例如 123 万、123 饼、123 条。": "Je ein zahlengleiches Chi in allen drei Farben, etwa 123 Zahlen, 123 Kreise und 123 Bambus.",
    "三门各有同一数字的刻子，例如 555 万、555 饼、555 条。": "Je ein zahlengleicher Pong in allen drei Farben, etwa 555 Zahlen, 555 Kreise und 555 Bambus.",
    "满足和牌条件但全部番种被规则排除，计作无番和。": "Die Gewinnbedingungen sind erfüllt, aber alle Spielbilder werden durch die Regeln ausgeschlossen: Null-Punkte-Hand.",
    "在牌山最后一张自摸和牌。": "Selbstgezogener Gewinn mit dem letzten Ziegel der Mauer.",
