    "136张无花牌，0翻可和；吃碰明杠后仅可自摸，打出混儿后本局不可和牌。庄家和牌连庄，其余轮庄。": "136 Ziegel ohne Blumen, Gewinn ab 0 Fan. Nach Chi, Pong oder offenem Kong nur Selbstzug; nach Abwurf eines Huner ist für diese Hand kein Gewinn mehr möglich. Bei eigenem Gewinn bleibt der Geber, sonst wechselt er.",
    "可选规则变体（默认关闭）": "Optionale Regelvarianten (standardmäßig aus)",
    "每张不按本体使用的混儿减1翻，最低保留1翻；原本0翻的和牌仍按0翻结算。": "Jeder nicht als sein tatsächlicher Ziegel verwendete Huner zieht 1 Fan ab, mindestens 1 Fan bleibt. Ein ursprünglicher Gewinn mit 0 Fan wird weiterhin mit 0 Fan abgerechnet.",
    "阅读北京麻将（吃碰提）完整规则与变体说明": "Vollständige Regeln und Varianten von Peking-Mahjong (Chi, Pong und Ti) lesen",
