    "MIL 2024：136张、十三张手牌，三门带幺九，可吃碰杠和报听。一条仅可在特殊杠中代牌；报听后看宝，六番封顶。三张特殊杠首次不补牌，以后每加一张补一张。": "MIL 2024: 136 Ziegel, dreizehn Handziegel, drei Farben mit Randziegeln. Chi, Pong, Kong und Wartemeldung erlaubt. Bambus-Eins ersetzt Ziegel nur in Sonderkongs. Nach Wartemeldung Bao ansehen; höchstens sechs Fan. Beim ersten Sonderkong aus drei Ziegeln kein Ersatz, danach je hinzugefügtem Ziegel ein Ersatzziegel.",
