    "起始与返点均为40000点，顺位点为0；每副144张，包含8张不同赖子。两副牌组交替使用。": "Start- und Rückgabepunkte jeweils 40000, Platzierungspunkte 0. Jeder Satz enthält 144 Ziegel mit 8 verschiedenen Jokern. Zwei Ziegelsätze werden abwechselnd verwendet.",
    "阅读夺彩麻将规则书与赖子图鉴": "Duocai-Regelbuch und Jokerübersicht lesen",
    "清空全部": "Alles leeren",
    "四家均预置 13 张手牌、8 张固定牌墙，另设 24 张公共牌墙。庄家开牌首摸取自固定墙；一家摸空后，剩余固定牌按东南西北接到公共墙前。": "Für jeden Spieler werden 13 Handziegel und 8 feste Mauerziegel vorbereitet; dazu kommen 24 gemeinsame Mauerziegel. Der erste Geberzug stammt aus der festen Mauer. Sobald ein Spieler diese leerzieht, werden die übrigen festen Ziegel in der Reihenfolge Ost, Süd, West, Nord vor die gemeinsame Mauer gesetzt.",
    "四家均预置 13 张手牌、14 张个人牌墙。庄家开牌首摸取自个人牌墙。无公共牌墙，不预先把庄家第一张摸牌放入手牌。": "Für jeden Spieler werden 13 Handziegel und 14 persönliche Mauerziegel vorbereitet. Der erste Geberzug stammt aus der persönlichen Mauer. Es gibt keine gemeinsame Mauer; der erste Geberziehziegel wird nicht vorab der Hand hinzugefügt.",
