    "起和点数": "Mindestgewinnpunkte",
    "只允许碰彩虹，不允许普通碰牌。每位玩家每局最多补牌两次。无色牌可组成对子或同色顺子，不能组成刻子或彩虹。": "Nur Regenbogen-Pong erlaubt, kein gewöhnlicher Pong. Jeder Spieler darf pro Hand höchstens zweimal ergänzen. Farblose Ziegel können Paare oder gleichfarbige Folgen bilden, aber keine Gleichzahlsätze oder Regenbögen.",
