    "和牌张按": "Gewinnziegel zählt als ",
    "MIL 2024：112张、十三张手牌，红中为万能牌，仅可自摸；可碰杠，不吃。最高四番，和牌后扎两鸟，流局退杠。": "MIL 2024: 112 Ziegel, dreizehn Handziegel, rote Drachen als universelle Joker, nur Selbstzug. Pong und Kong erlaubt, kein Chi. Höchstens vier Fan; nach Gewinn zwei Vögel ziehen, bei Unentschieden Kongpunkte zurückzahlen.",
    "阅读 MIL 红中规则书": "MIL-Hongzhong-Regelbuch lesen",
    "九江麻将是九江地区一个没落的麻将规则，目前九江地区通行红中麻将，本规则是芋蔗凭借小时候的记忆和一定程度上的改良复现的一种失传规则，如发现任何问题或者能够提供九江麻将的资料的玩家可以联系Q2264033554": "Jiujiang-Mahjong ist ein in der Region Jiujiang zurückgegangenes Regelwerk; heute ist dort Hongzhong-Mahjong verbreitet. Yuzhe hat diese verlorenen Regeln anhand seiner Kindheitserinnerungen mit einigen Anpassungen wiederhergestellt. Bei Problemen oder mit Informationen zu Jiujiang-Mahjong bitte QQ2264033554 kontaktieren.",
    "下载九江麻将规则书": "Jiujiang-Mahjong-Regelbuch herunterladen",
    "回复": "Antworten",
