    "写下回复…": "Antwort schreiben …",
    "传统84张，东南西三席，5番起和。飞可作百搭或当花；花套与杠即时结算，和牌后另比输家花分与三家飞牌。": "Traditionell 84 Ziegel, drei Sitze Ost, Süd und West, Gewinn ab 5 Fan. Fei dient als Joker oder Blume. Blumensets und Kongs werden sofort abgerechnet. Nach dem Gewinn werden zusätzlich die Blumenpunkte der Verlierer und die Fei-Ziegel aller drei Spieler verglichen.",
