    "山西麻将 · MIL试行2023版。136张、十三张手牌、无花无癞子；须暗扣报听，有和必和，和牌时结杠。": "Shanxi-Mahjong · MIL-Testversion 2023. 136 Ziegel, dreizehn Handziegel, keine Blumen oder Joker. Wartemeldung mit verdecktem Abwurf erforderlich; mögliche Gewinne müssen angenommen werden. Kongabrechnung beim Gewinn.",
    "局时是每局额外思考储备，默认20秒；每次操作先使用步时，默认5秒。零局时只使用步时。": "Die Handzeit ist die zusätzliche Bedenkreserve je Hand, standardmäßig 20 Sekunden. Jede Aktion nutzt zuerst die Zugzeit, standardmäßig 5 Sekunden. Bei Handzeit null gilt nur die Zugzeit.",
