    "SPGG 2024 四人麻将：148张牌，1台起和、5台封顶，400分起分。花季与动物婚配、杠即时支付，庄家和牌或无杠流局连庄。": "SPGG 2024, vier Spieler: 148 Ziegel, mindestens 1 und höchstens 5 Tai, 400 Startpunkte. Blumen- und Jahreszeitensets, Tierpaare und Kongs werden sofort bezahlt. Bei Gebergewinn oder Unentschieden ohne Kong bleibt der Geber.",
