    "支持本赛事／基地的手动牌山、复现牌山、密钥牌山；规则须与房间一致。": "Unterstützt manuelle, wiederhergestellte und Schlüssel-Mauern dieses Turniers oder Clubraums. Die Regeln müssen zum Raum passen.",
    "自动生成复式密钥": "Duplikatschlüssel automatisch erzeugen",
    "每个房间生成并绑定一个独立密钥，本次创建": "Jeder Raum erhält einen eigenen erzeugten und zugeordneten Schlüssel. Diesmal werden ",
    "个密钥。花牌使用上方设置，局数跟随密钥。": " Schlüssel erstellt. Blumen folgen der obigen Einstellung, die Handzahl dem Schlüssel.",
