    "个。额度由场馆管理员共用，北京时间零点刷新。": ". Das Kontingent wird von den Administratoren des Veranstaltungsorts geteilt und um Mitternacht Pekinger Zeit erneuert.",
    "阅读温州 MIL 2024 规则书": "Wenzhou-MIL-Regelbuch 2024 lesen",
    "MIL 2025：136张，皮癞单张杠；必须开口，逐家六番起和。末四张只能自摸或过，七皮、十杠途中结算，轮庄。鸣牌响应为3秒。": "MIL 2025: 136 Ziegel, Einzelziegelkongs mit Pi und Lai. Offener Ruf erforderlich, mindestens sechs Fan je Gegner. Bei den letzten vier Ziegeln nur Selbstzug oder passen. Sieben Pi und Zehn Kongs werden vorzeitig abgerechnet; der Geber wechselt. Rufantwortzeit 3 Sekunden.",
    "阅读 MIL 武汉规则书": "MIL-Wuhan-Regelbuch lesen",
    "144张、十三张手牌；可吃碰杠，逐张补花。2花自摸、3花放冲、1花独吊；固定牌型已含胡牌底花。": "144 Ziegel, dreizehn Handziegel. Chi, Pong und Kong erlaubt; Blumen einzeln ersetzen. 2 Blumen für Selbstzug, 3 für Abwurfgewinn, 1 für Einzelwarten. Feste Handformen enthalten bereits die Grundblumen des Gewinns.",
