    "例如：第一轮 · A 组": "Zum Beispiel: Erste Runde · Gruppe A",
    "川麻牌山布局": "Sichuan-Maueraufteilung",
    "庄家也只预置 13 张，开牌时再从自己的牌墙头摸一张。东南西北方位固定，庄家依次轮转。": "Auch für den Geber werden nur 13 Ziegel vorbereitet. Zu Beginn zieht er einen weiteren vom Anfang seiner Mauer. Ost, Süd, West und Nord bleiben fest; die Geberrolle wechselt der Reihe nach.",
