    "上传内容须由你拥有版权，或取得明确允许非商业使用和公开分享的许可证。": "Du musst das Urheberrecht an hochgeladenen Inhalten besitzen oder eine Lizenz haben, die nichtkommerzielle Nutzung und öffentliches Teilen ausdrücklich erlaubt.",
