    "查看已解除锁定的密钥、创建时间、解锁时间和关联对局。": "Freigegebene Schlüssel, Erstellungszeit, Freigabezeit und zugehörige Partien ansehen.",
    "创建复式密钥 →": "Duplikatschlüssel erstellen →",
    "输入复式密钥；留空查看最近解除锁定的密钥": "Duplikatschlüssel eingeben; leer lassen für zuletzt freigegebene Schlüssel",
    "锁定的密钥不公开。解除锁定后可在这里查询，且不能重新锁定。复式对局不保存本地牌谱。": "Gesperrte Schlüssel sind nicht öffentlich. Nach Freigabe sind sie hier abrufbar und können nicht erneut gesperrt werden. Duplikatpartien speichern keine lokalen Spielprotokolle.",
    "创建者 / 所属赛事": "Ersteller / Turnier",
