    "仅自摸；蓝色牌为杠补自动弃牌，不能吃碰杠。宝牌杠弃不计飞宝。": "Nur Selbstzug. Blaue Ziegel sind automatisch abgeworfene Kongersatzziegel und dürfen nicht für Chi, Pong oder Kong gerufen werden. Ein als Kongersatz abgeworfener Bonusziegel zählt nicht als Feibao.",
