    "初始 R 为 1500，仅系统匹配计分，自建房不计。": "Der anfängliche R-Wert beträgt 1500. Nur die Systemspielersuche zählt; eigene Räume nicht.",
    "预期胜率 = 1 / (1 + 10^((对手 R − 自己 R) / 2000))。": "Erwartete Gewinnquote = 1 / (1 + 10^((R des Gegners − eigenes R) / 2000)).",
    "变化值 = 32 ×（实际结果 − 预期胜率），结果四舍五入为整数；胜为 1，负为 0。": "Änderung = 32 × (tatsächliches Ergebnis − erwartete Gewinnquote), auf eine ganze Zahl gerundet; Sieg = 1, Niederlage = 0.",
    "历史积分按迁移前原分 + 500 修正，之后已结算的积分变化、胜负和场数保留。": "Historische Punkte wurden auf den ursprünglichen Wert vor der Migration + 500 angepasst. Später abgerechnete Punkteänderungen, Siege, Niederlagen und Partiezahlen bleiben erhalten.",
