    "本局没有提交猜测": "In dieser Runde keine Vermutung abgegeben",
    "秒后自动进入下一局": " Sekunden bis zur nächsten Runde",
    "再来一局": "Noch eine Runde",
    "点击下方牌面添加手牌；点击副露框后，只有能组成合法牌组的牌会高亮可点。 手牌 + 副露合计最多 14 张，所有牌必须分成 3 张及以上的合法牌组，无雀头。 自摸支持连续加杠预测；手牌为空时也可输入副露，查看可摸入的和牌张。": "Klicke unten auf Ziegel, um sie der Hand hinzuzufügen. Nach Auswahl eines Figurenfelds sind nur Ziegel hervorgehoben und anklickbar, die einen gültigen Satz bilden können. Hand und offene Sätze umfassen zusammen höchstens 14 Ziegel. Alle Ziegel müssen gültige Sätze aus mindestens 3 Ziegeln bilden; es gibt kein Abschlusspaar. Für Selbstzug sind Vorhersagen aufeinanderfolgender Kongerweiterungen möglich. Auch bei leerer Hand können offene Sätze eingegeben werden, um ziehbare Gewinnziegel zu sehen.",
    "输入手牌或副露后计算和牌与预测": "Hand oder offene Sätze eingeben, um Gewinne und Vorhersagen zu berechnen",
    "加杠顺序": "Reihenfolge der Kongerweiterungen",
    "加入副露 #": "Zu offener Figur hinzufügen #",
    "当前牌型未成和牌；可查看下方摸入一张后的预测。": "Die aktuelle Hand ist noch keine Gewinnhand. Unten stehen Vorhersagen nach dem Ziehen eines Ziegels.",
    "摸牌后的和牌预测（": "Gewinnvorhersagen nach einem Zug (",
    "种）": " Arten)",
    "“仅自摸”需摸入后按顺序加杠；其他玩家的弃牌不能用于这种和法。展开查看加杠步骤与最终牌型。": "„Nur Selbstzug“ erfordert nach dem Ziehen Kongerweiterungen in der angegebenen Reihenfolge. Abwürfe anderer Spieler können für diese Gewinnart nicht verwendet werden. Aufklappen für die Erweiterungsschritte und die endgültige Handform.",
    "仅自摸 ·": "Nur Selbstzug · ",
    "捉和": "Abwurfgewinn",
    "分 · 自摸": " Punkte · Selbstzug ",
    "仅自摸：": "Nur Selbstzug: ",
    "；和牌": "; Gewinn ",
    "12/13 张显示向听与进张效率，14 张显示切牌效率。 已和牌仍会列出可继续扩展的进张；一向听、两向听、三向听及以上都会计算能减少向听的进张。 每种牌只有一张。输入为空时随机生成 14 张。计算在浏览器本地完成。": "Bei 12/13 Ziegeln werden Shanten und Verbesserungseffizienz angezeigt, bei 14 Ziegeln die Abwurfeffizienz. Auch fertige Gewinnhände zeigen weiter ausbaufähige Verbesserungsziegel. Für ein, zwei, drei und mehr Shanten werden alle Ziegel berechnet, die Shanten verringern. Jede Ziegelart existiert nur einmal. Bei leerer Eingabe werden zufällig 14 Ziegel erzeugt. Die Berechnung erfolgt lokal im Browser.",
